// Newly written explanations and examples; the textbook pages are a curriculum reference only.
const E = (spanish, english, tense = 'mixed') => ({ spanish, english, tense });
const B = (heading, body, examples = [], tip = '', table) => ({ heading, body, examples, tip, ...(table ? { table } : {}) });

export const unitGuideSections = [
  {
    id: 'story-tools', title: 'Time markers, connectors and reactions', subtitle: 'Choose the relationship you want the reader to follow', units: [9, 10],
    intro: 'A good account helps the reader locate a period, follow events, understand reasons and recognise reactions. These expressions organise meaning. They are useful clues to the story, but they do not select a verb tense automatically.',
    blocks: [
      B('Open an anecdote and establish its reference time', '{es}Una vez{/es} and {es}un día{/es} introduce a particular occasion; {es}el otro día{/es} usually introduces one in the recent past. {es}En aquella época{/es} and {es}en aquellos tiempos{/es} refer to a past period already established. {es}De niño{/es}, {es}de joven{/es} and {es}cuando tenía quince años{/es} locate a stage of life. First establish which time the account refers to, then decide how to present the situation within it.', [E('El otro día entré en una librería. Dentro, una mujer buscaba un mapa.', 'The opening introduces one recent occasion; the second sentence looks inside the scene.'), E('Mi abuelo trabajaba en el puerto en 1965. En aquella época, vivía cerca del mar.', '{es}En aquella época{/es} refers back to the period established by 1965.')], 'An expression such as {es}en 1965{/es} can accompany either tense: {es}vivía{/es} describes life within that year; {es}vivió allí todo el año{/es} presents a complete stay.'),
      B('Order events, show overlap and highlight a surprise', '{es}Luego{/es}, {es}más tarde{/es} and {es}después{/es} place events later; {es}poco después{/es} specifies a short interval. {es}En ese momento{/es} points to the reference moment just mentioned. {es}Mientras{/es} and {es}mientras tanto{/es} connect overlapping activities. {es}De repente{/es} highlights an unexpected onset, not simply something that happens next. {es}Entonces{/es} can mean at that moment, then, or consequently: the surrounding account identifies its role.', [E('Mientras yo consultaba el mapa, Julia compró los billetes.', 'The activities overlap. Buying the tickets is presented as a whole within the ongoing consultation.'), E('Llegó el técnico. En ese momento le enseñé la pantalla; poco después volvió la imagen.', 'One marker anchors showing the screen at the arrival; the next locates a later event.'), E('La sala estaba en silencio y, de repente, sonó una alarma.', 'The marker highlights a sound that breaks unexpectedly into the scene.')], '{es}Al final{/es} introduces an eventual outcome after the events or difficulties. {es}Finalmente{/es} can also close a sequence. It is the relationship within the whole paragraph that matters.'),
      B('Explain a reason, a consequence or a discovery', '{es}Porque{/es} introduces a reason. {es}Así que{/es} and {es}por eso{/es} introduce a consequence. {es}Resulta que{/es} reveals information, often explaining something puzzling; it does not necessarily introduce the next chronological action. In conversational narration, the fixed present phrase {es}resulta que{/es} can introduce information about a past situation.', [E('No entramos porque la sala estaba cerrada.', 'The closed room explains the decision; the explanation is background.'), E('La sala estaba cerrada, así que buscamos otra entrada.', 'The search is presented as a consequence of the closure.'), E('Busqué mi abrigo por todo el teatro. Resulta que mi hermana lo llevaba puesto.', 'The revelation describes a situation already in place, with imperfect {es}llevaba{/es}.')], 'Changing {es}porque{/es} to {es}así que{/es} changes the logical direction. Read both clauses and ask which explains the other. A connector is more than a decoration between sentences.'),
      B('Build an argument about past and present', '{es}Por ejemplo{/es} introduces a concrete illustration; {es}además{/es} adds another point supporting the same argument. {es}Pero{/es} and {es}sin embargo{/es} introduce a contrast or qualification. To frame an opinion, use {es}creo que{/es} or {es}pienso que{/es}; {es}estoy de acuerdo{/es} and {es}no estoy de acuerdo{/es} express agreement or disagreement. A partly shared view can use {es}sí, pero…{/es} . These present expressions can introduce discussion of past situations.', [E('Creo que ahora es más fácil estudiar. Por ejemplo, tenemos una biblioteca cerca.', 'A concrete example supports an opinion about the present.'), E('Antes había una sola sala. Además, cerraba muy pronto.', 'A second limitation supports the same argument about the earlier period.'), E('Ahora hay más bibliotecas; sin embargo, algunas cierran demasiado pronto.', 'The second point qualifies the positive comparison rather than explaining its cause.')], 'Several connectors may produce grammatical sentences. In practice, choose the requested function and intended meaning. Natural alternatives receive full credit when they express that same relationship.'),
      B('Describe historical periods and social changes', 'Use {es}en el siglo XX{/es} for the century, {es}en los años noventa{/es} or {es}en la década de los noventa{/es} for a decade, and {es}a principios{/es}, {es}a mediados{/es} or {es}a finales de…{/es} for an approximate part of a period. Useful historical vocabulary includes {es}democracia{/es}, {es}dictadura{/es}, {es}derechos{/es}, {es}libertad de expresión{/es}, {es}educación{/es}, {es}aprobar una ley{/es}, {es}prohibir{/es} and {es}reconocer un derecho{/es}. A remembered situation and an event that changes it need different viewpoints.', [E('A mediados del siglo XX, mi abuela vivía junto a una imprenta.', 'The period locates a remembered family situation.'), E('En la exposición escolar, un panel describía la vida durante una dictadura. Luego, nuestra guía explicó qué significaba la libertad de expresión.', 'The panel is part of the scene; the guide’s explanation is presented as a whole episode.'), E('Antes la asociación no tenía local. Ahora tiene uno, pero todavía necesita más libros.', 'Past and present contrast; {es}todavía{/es} identifies something that continues.')], '{es}Antes{/es} contrasts with {es}ahora{/es}, {es}actualmente{/es} and {es}hoy en día{/es}. {es}Ya no{/es} marks something that has stopped; {es}todavía{/es} marks something that continues. With a verb, write {es}ya no vive aquí{/es}, rather than {es}ya vive no aquí{/es}. Historical stories identify fictional witnesses separately from documented events.'),
      B('Show an emotion as a state or as a reaction', '{es}Estaba nerviosa{/es} and {es}tenía miedo{/es} describe feelings within a scene. {es}Me puse nerviosa{/es} marks a change of state; {es}me dio miedo{/es} presents something as the trigger for fear. {es}Me emocioné{/es}, {es}me enfadé{/es}, {es}me reí{/es} and {es}lloré de alegría{/es} can present reactions as events. Passing through an emotional episode can also be summarised: {es}pasé mucho miedo{/es}. The emotion itself does not determine the tense.', [E('Antes de hablar, estaba nerviosa. Al ver a mi familia, me puse a sonreír.', 'An existing state contrasts with a new reaction.'), E('Oí un golpe y me dio miedo. Después descubrí que era una ventana.', 'Fear is presented as a reaction to the sound; {es}era{/es} identifies its cause.'), E('Al escuchar la noticia, lloré de alegría. Mi hermano dijo: «¡Qué emoción!»', 'A past reaction is followed by a direct emotional response.')], 'Useful responses include {es}¡Qué alegría!{/es}, {es}¡Qué pena!{/es}, {es}¡Qué miedo!{/es}, {es}¡Qué vergüenza!{/es} and {es}¡Qué nervios!{/es} Choose the feeling supported by the situation; a sad event does not necessarily make every character sad.')
    ],
    practice: ['story-connectors', 'time-and-change', 'voices-and-reactions', 'writing']
  },
  {
    id: 'past-progressive', title: '{es}Estar + gerundio{/es} in the past', subtitle: 'An unfolding activity can also form a complete episode', units: [8, 10],
    diagrams: ['progressive-conversation', 'progressive-painting'],
    intro: '{es}Estar + gerundio{/es} focuses on an activity as it unfolds. The tense on {es}estar{/es} determines whether we view it from within at a reference moment or sum up a bounded period of activity. Progressive does not mean imperfect by default.',
    blocks: [
      B('Build the construction and agree with the subject', 'Conjugate {es}estar{/es}; keep the gerund unchanged for every subject. Regular gerunds end in {es}-ando{/es} for {es}-ar{/es} verbs and {es}-iendo{/es} for {es}-er{/es} and {es}-ir{/es} verbs. We say {es}estaba preparando{/es} and {es}estaban preparando{/es}: the auxiliary changes, while {es}preparando{/es} does not. If the gerund is already printed beside a gap, write only the auxiliary.', [E('Yo estaba preparando la mesa y mis hermanos estaban preparando la comida.', 'Each auxiliary agrees with its subject; {es}preparando{/es} stays unchanged.', 'imperfect')], 'Do not join two conjugated verbs: {es}estuvo preparó{/es} is incorrect. {es}Estuvo preparando{/es} combines a conjugated auxiliary with a gerund.', { headers: ['Subject', 'Imperfect auxiliary', 'Preterite auxiliary'], rows: [['{es}yo{/es}', '{es}estaba{/es}', '{es}estuve{/es}'], ['{es}tú{/es}', '{es}estabas{/es}', '{es}estuviste{/es}'], ['{es}él / ella / usted{/es}', '{es}estaba{/es}', '{es}estuvo{/es}'], ['{es}nosotros/as{/es}', '{es}estábamos{/es}', '{es}estuvimos{/es}'], ['{es}vosotros/as{/es}', '{es}estabais{/es}', '{es}estuvisteis{/es}'], ['{es}ellos / ellas / ustedes{/es}', '{es}estaban{/es}', '{es}estuvieron{/es}']] }),
      B('Show what was in progress at a reference moment', '{es}Estaba + gerundio{/es} places us inside an activity at the time of another event, a photograph or a remembered observation. The activity does not have to stop when the event happens. The sentence simply locates that event within its development. The simple imperfect can often express a similar ongoing situation; the progressive explicitly focuses on it unfolding.', [E('Cuando llegó el mensaje, estaba buscando las llaves.', 'The search was already in progress at the message. The message need not end it.', 'imperfect'), E('En la foto, mis primas estaban leyendo en el sofá.', 'The photograph gives one moment within the reading.', 'imperfect'), E('Buscaba las llaves cuando llegó el mensaje.', 'The simple imperfect can also give the ongoing background in this context.', 'imperfect')], 'In activities that specify {es}estar + gerundio{/es}, practise that construction. In freer stories, a simple imperfect may also be natural; feedback distinguishes the requested form from a different grammatical wording.'),
      B('Sum up a bounded period of activity', '{es}Estuve + gerundio{/es} can present the whole relevant period during which an activity unfolded. {es}Desde las cuatro hasta las seis{/es}, {es}toda la mañana{/es} and the next event may establish its limits. The period can be short or long. The construction does not necessarily say the task reached its goal or that an object was finished.', [E('Estuve preparando la presentación dos horas y después salí; todavía faltaban tres diapositivas.', 'The preparation period is complete; the presentation is explicitly unfinished.', 'preterite'), E('Estuvieron leyendo de cinco a siete y dejaron los libros a medias.', 'The reading session has limits, but finishing the books is not asserted.', 'preterite'), E('Estuvimos buscando diez minutos y luego llamamos al portero.', 'The whole search interval is bounded by the next action.', 'preterite')], 'A complete episode of reading is not the same claim as finishing a book. Compare {es}estuve leyendo el libro{/es}, which sums up reading activity, and {es}leí el libro entero{/es}, which presents the entire book as read.'),
      B('Compare two views of the same real activity', 'Both forms can describe the same afternoon. A question about a particular moment invites a view from inside; a retrospective timetable can summarise the whole period. An activity lasting years can have the preterite viewpoint, while a few seconds can have the imperfect viewpoint. Time expressions help define the view, but do not select the form on their own.', [E('A las cinco estaba hablando con Ana.', 'Five is a reference point within the conversation.', 'imperfect'), E('Estuve hablando con Ana de cuatro a seis.', 'The entire conversation period is summed up.', 'preterite'), E('Durante aquel mes, a las cinco normalmente estaba hablando con Ana.', '{es}Durante{/es} frames a month; the sentence describes the usual activity at five, not one complete conversation.', 'imperfect')], 'Ask what the time expression measures: the complete activity, a point inside it, or the setting for a routine. Avoid the shortcuts “long = imperfect” and “a duration word = preterite”.'),
      B('Learn useful irregular gerunds and pronoun positions', 'Common gerunds include {es}leyendo{/es}, {es}oyendo{/es}, {es}yendo{/es}, {es}durmiendo{/es}, {es}pidiendo{/es}, {es}sintiendo{/es} and {es}riendo{/es}. These changes belong to the gerund, which stays the same after either {es}estaba{/es} or {es}estuve{/es}. A pronoun can precede the conjugated {es}estar{/es} or attach to the gerund: {es}se estaban riendo / estaban riéndose{/es}. Both positions give the same reading; attachment may require a written accent.', [E('Laura estaba pidiendo ayuda cuando llegamos.', '{es}Pedir{/es} has the gerund {es}pidiendo{/es}, regardless of the auxiliary tense.'), E('Se estuvieron riendo cinco minutos. Estuvieron riéndose cinco minutos.', 'Both pronoun positions express the same bounded episode.', 'preterite')], 'For a cue with {es}reírse{/es}, include {es}se{/es}. Do not repeat it in both positions: {es}se estaban riéndose{/es} is incorrect.', { headers: ['Infinitive', 'Gerund'], rows: [['{es}leer{/es}', '{es}leyendo{/es}'], ['{es}oír{/es}', '{es}oyendo{/es}'], ['{es}ir{/es}', '{es}yendo{/es}'], ['{es}dormir{/es}', '{es}durmiendo{/es}'], ['{es}pedir{/es}', '{es}pidiendo{/es}'], ['{es}sentir{/es}', '{es}sintiendo{/es}'], ['{es}reír(se){/es}', '{es}riendo / riéndose{/es}']] })
    ],
    practice: ['progressive-past', 'duration', 'process', 'alternatives']
  }
];
